 static float R(float a,float b)=>Mathf.Lerp(a,b,(float)azar.NextDouble());
 public static float Ruta(float z)=>LimitesCaminoInca.Centro(z);
 public static float Base(float z)=>4+1.8f*Mathf.Sin(z*.018f)+Mathf.Max(0,z-190)*.018f;
 public static float Altura(float x,float z){float dist=Mathf.Abs(x-Ruta(z));float borde=Mathf.SmoothStep(0,1,Mathf.Clamp01((dist-5)/43));float colina=8+20*Mathf.PerlinNoise(x*.018f+21,z*.017f+12)+7*Mathf.PerlinNoise(x*.05f,z*.04f);float detalle=(Mathf.PerlinNoise(x*.11f+9,z*.12f)-.5f)*Mathf.SmoothStep(0,1,dist/12)*1.8f;float y=Base(z)+borde*colina+detalle;float rio=Mathf.Exp(-Mathf.Pow(Mathf.Abs(z-164)/6.7f,4));return Mathf.Lerp(y,-2.4f,rio);}
 static Vector3 Punto(float x,float z)=>new Vector3(x,terreno.SampleHeight(new Vector3(x,0,z))+terreno.transform.position.y,z);
 static T Asset<T>(T obj,string nombre)where T:UnityEngine.Object{string path=D+nombre;var old=AssetDatabase.LoadAssetAtPath<T>(path);if(old==null){AssetDatabase.CreateAsset(obj,path);return obj;}EditorUtility.CopySerialized(obj,old);UnityEngine.Object.DestroyImmediate(obj);EditorUtility.SetDirty(old);return old;}
