 static Texture2D Textura(string nombre,Color a,Color b,float frecuencia,bool normal=false){int N=256;var tex=new Texture2D(N,N,TextureFormat.RGBA32,true, !normal?false:true);var pixels=new Color[N*N];var alturas=new float[N*N];for(int y=0;y<N;y++)for(int x=0;x<N;x++){float u=x/(float)N,v=y/(float)N;float n=Mathf.PerlinNoise(u*frecuencia+13,v*frecuencia+7)*.55f+Mathf.PerlinNoise(u*frecuencia*3+4,v*frecuencia*3+2)*.28f+(float)azar.NextDouble()*.17f;alturas[y*N+x]=n;pixels[y*N+x]=Color.Lerp(a,b,n);}if(normal)for(int y=0;y<N;y++)for(int x=0;x<N;x++){float dx=alturas[y*N+(x+1)%N]-alturas[y*N+(x+N-1)%N],dy=alturas[((y+1)%N)*N+x]-alturas[((y+N-1)%N)*N+x];Vector3 n=new Vector3(-dx*1.4f,-dy*1.4f,1).normalized;pixels[y*N+x]=new Color(n.x*.5f+.5f,n.y*.5f+.5f,n.z*.5f+.5f,1);}tex.SetPixels(pixels);tex.Apply();string path=D+nombre+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.wrapMode=TextureWrapMode.Repeat;imp.anisoLevel=8;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static void PrepararMateriales(){
 roca=AssetDatabase.LoadAssetAtPath<Material>("Assets/Personajes/Chasqui/MaterialPiedra.mat");roca.enableInstancing=true;EditorUtility.SetDirty(roca);corteza=Mat("Corteza",new Color(.29f,.23f,.15f));corteza.mainTexture=Textura("CortezaColor",new Color(.24f,.19f,.13f),new Color(.65f,.56f,.36f),12);corteza.mainTextureScale=new Vector2(2,1);
 madera=Mat("Madera",new Color(.35f,.24f,.12f));madera.mainTexture=corteza.mainTexture;madera.mainTextureScale=new Vector2(1,3);cuerda=Mat("Fibra",new Color(.57f,.43f,.23f));paja=Mat("TechoIchu",new Color(.65f,.50f,.27f));paja.mainTexture=Textura("PajaColor",new Color(.43f,.30f,.13f),new Color(.86f,.73f,.40f),35);paja.mainTextureScale=new Vector2(4,6);pared=Mat("PiedraMuro",new Color(.43f,.42f,.34f));pared.mainTexture=Textura("MuroColor",new Color(.30f,.31f,.26f),new Color(.72f,.68f,.53f),15);tela=Mat("Cochinilla",new Color(.52f,.11f,.075f));oro=Mat("QuipuOcre",new Color(.95f,.64f,.16f));oro.EnableKeyword("_EMISSION");oro.SetColor("_EmissionColor",new Color(.13f,.055f,.004f));
 int N=128;var tex=new Texture2D(N,N,TextureFormat.RGBA32,true);var cols=new Color[N*N];Vector2[] puntos={new Vector2(.32f,.33f),new Vector2(.60f,.22f),new Vector2(.40f,.64f),new Vector2(.73f,.52f),new Vector2(.63f,.79f)};for(int y=0;y<N;y++)for(int x=0;x<N;x++){Vector2 uv=new Vector2(x/(float)N,y/(float)N);float alpha=0;foreach(var c in puntos){Vector2 d=uv-c;float e=d.x*d.x/.025f+d.y*d.y/.009f;alpha=Mathf.Max(alpha,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.75f,1,e)));}float ruido=Mathf.PerlinNoise(x*.24f,y*.24f);cols[y*N+x]=new Color(.36f+ruido*.25f,.45f+ruido*.26f,.17f+ruido*.19f,alpha);}tex.SetPixels(cols);tex.Apply();string path=D+"Hojas.png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.alphaIsTransparency=true;importer.SaveAndReimport();hojas=Mat("Follaje",new Color(.58f,.69f,.44f));hojas.shader=Shader.Find("Chasqui/Follaje valle");hojas.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);hojasClaras=Mat("Ichu",new Color(.84f,.78f,.46f));hojasClaras.shader=hojas.shader;hojasClaras.mainTexture=TexturaIchu();
 }
 static Texture2D TexturaIchu(){int N=128;var tex=new Texture2D(N,N,TextureFormat.RGBA32,true);var pix=new Color[N*N];for(int y=0;y<N;y++)for(int x=0;x<N;x++){float u=x/(float)N,v=y/(float)N,alpha=0;for(int i=0;i<7;i++){float hi=.7f+.28f*Mathf.Sin(i*2.3f+1),centro=(i+.5f)/7+Mathf.Sin(v*2.8f+i)*.07f*v,ancho=.014f*(1-v/hi);if(v<hi)alpha=Mathf.Max(alpha,Mathf.Clamp01((ancho-Mathf.Abs(u-centro))*180));}pix[y*N+x]=new Color(.48f+v*.25f,.43f+v*.25f,.18f+v*.18f,alpha);}tex.SetPixels(pix);tex.Apply();string path=D+"Ichu.png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.alphaIsTransparency=true;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static void CrearTerreno(){
 int res=513;var td=new TerrainData{heightmapResolution=res,size=new Vector3(220,60,350),alphamapResolution=256,baseMapResolution=512};var h=new float[res,res];for(int z=0;z<res;z++)for(int x=0;x<res;x++)h[z,x]=(Altura(-110+x*220f/(res-1),z*350f/(res-1))+6)/60;td.SetHeights(0,0,h);
 Color[] a={new Color(.17f,.22f,.095f),new Color(.30f,.22f,.13f),new Color(.26f,.28f,.26f),new Color(.43f,.38f,.25f)};Color[] b={new Color(.47f,.48f,.23f),new Color(.61f,.49f,.31f),new Color(.62f,.61f,.52f),new Color(.76f,.68f,.46f)};
 var layers=new TerrainLayer[4];for(int i=0;i<4;i++){var layer=new TerrainLayer{diffuseTexture=Textura("Suelo"+i,a[i],b[i],i==2?12:24),normalMapTexture=Textura("NormalSuelo"+i,a[i],b[i],18,true),tileSize=new Vector2(i==2?8:5,i==2?8:5),smoothness=.08f,normalScale=.7f};layers[i]=Asset(layer,"Suelo"+i+".terrainlayer");}td.terrainLayers=layers;
 var alpha=new float[256,256,4];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float wx=-110+x*220f/255,wz=z*350f/255;float dist=Mathf.Abs(wx-Ruta(wz));float sendero=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.3f,4.6f+Mathf.PerlinNoise(wx*.4f,wz*.4f),dist));float pendiente=td.GetSteepness(x/255f,z/255f);float piedra=Mathf.SmoothStep(0,1,Mathf.InverseLerp(25,52,pendiente));float arena=Mathf.Exp(-Mathf.Pow((Mathf.Abs(wz-164)-8)/4,2))*.85f;float pasto=Mathf.Max(0,1-sendero-piedra-arena);float sum=sendero+piedra+arena+pasto;alpha[z,x,0]=pasto/sum;alpha[z,x,1]=sendero/sum;alpha[z,x,2]=piedra/sum;alpha[z,x,3]=arena/sum;}td.SetAlphamaps(0,0,alpha);td=Asset(td,"ValleTerreno.asset");td.terrainLayers=layers;td.SetHeights(0,0,h);td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);var o=Terrain.CreateTerrainGameObject(td);o.name="Terreno · Valle y sendero";o.transform.position=new Vector3(-110,-6,0);terreno=o.GetComponent<Terrain>();terreno.heightmapPixelError=5;terreno.basemapDistance=180;terreno.drawInstanced=true;var terrainMat=Mat("Terreno",Color.white);terrainMat.shader=Shader.Find("Nature/Terrain/Standard");terreno.materialTemplate=terrainMat;
 }
 static void CrearSendero(){var g=new Geo();for(int i=0;i<=600;i++){float z=12+i*.52f;float x=Ruta(z),ancho=1.8f+Mathf.PerlinNoise(z*.2f,13)*.45f;for(int k=0;k<5;k++){float u=k/4f;float xx=x+(u*2-1)*ancho;g.v.Add(Punto(xx,z)+Vector3.up*.045f);g.uv.Add(new Vector2(u,z/4));}}for(int i=0;i<600;i++){float z=12+i*.52f;if(z>150&&z<177)continue;for(int k=0;k<4;k++){int a=i*5+k;g.Tri(a,a+5,a+1);g.Tri(a+1,a+5,a+6);}}var m=Mat("CaminoTierra",new Color(.77f,.66f,.49f));m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(D+"Suelo1.png");m.mainTextureScale=Vector2.one;Malla("Sendero · tierra compactada",Asset(g.Mesh("Camino del valle"),"Camino.asset"),m,camino,Vector3.zero,Vector3.one);}
 static void CrearIluminacion(){var sun=new GameObject("Sol · Tarde en el valle").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(42,-32,0);sun.color=new Color(1,.89f,.72f);sun.intensity=1.35f;sun.shadows=LightShadows.Soft;sun.shadowBias=.035f;RenderSettings.sun=sun;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.46f,.62f,.77f);RenderSettings.ambientEquatorColor=new Color(.38f,.43f,.36f);RenderSettings.ambientGroundColor=new Color(.20f,.22f,.14f);RenderSettings.ambientIntensity=1;RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.0025f;RenderSettings.fogColor=new Color(.59f,.71f,.76f);var sky=Mat("Cielo",Color.white);sky.shader=Shader.Find("Skybox/Procedural");sky.SetColor("_SkyTint",new Color(.57f,.68f,.77f));sky.SetColor("_GroundColor",new Color(.35f,.38f,.29f));sky.SetFloat("_AtmosphereThickness",.85f);sky.SetFloat("_Exposure",1.12f);RenderSettings.skybox=sky;QualitySettings.shadowDistance=100;QualitySettings.shadows=ShadowQuality.All;QualitySettings.antiAliasing=4;}
 class Geo{public List<Vector3> v=new List<Vector3>();public List<int> t=new List<int>();public List<Vector2> uv=new List<Vector2>();public void Tri(int a,int b,int c){t.Add(a);t.Add(b);t.Add(c);}public Mesh Mesh(string n){var m=new Mesh{name=n,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateBounds();return m;}}
 static void Tubo(Geo g,Vector3 a,Vector3 b,float ra,float rb,int lados=7){Vector3 dir=(b-a).normalized,right=Vector3.Cross(dir,Vector3.forward).normalized;if(right.sqrMagnitude<.1f)right=Vector3.right;Vector3 forward=Vector3.Cross(dir,right);int start=g.v.Count;for(int j=0;j<2;j++)for(int i=0;i<=lados;i++){float ang=i*2*Mathf.PI/lados;g.v.Add((j==0?a:b)+(right*Mathf.Cos(ang)+forward*Mathf.Sin(ang))*(j==0?ra:rb));g.uv.Add(new Vector2(i/(float)lados,j));}for(int i=0;i<lados;i++){int k=start+i;g.Tri(k,k+lados+1,k+1);g.Tri(k+1,k+lados+1,k+lados+2);}}
 static void Hoja(Geo g,Vector3 p,float size,Quaternion q){int n=g.v.Count;Vector3[] v={new Vector3(-.5f,-.5f,0),new Vector3(.5f,-.5f,0),new Vector3(.5f,.5f,0),new Vector3(-.5f,.5f,0)};Vector2[] uv={Vector2.zero,Vector2.right,Vector2.one,Vector2.up};for(int i=0;i<4;i++){g.v.Add(p+q*(v[i]*size));g.uv.Add(uv[i]);}g.Tri(n,n+1,n+2);g.Tri(n,n+2,n+3);}
 static void ArbolMesh(int variante,out Mesh troncos,out Mesh hojasMesh){var g=new Geo();var leaf=new Geo();float alto=variante==0?5.8f:4.2f;Vector3 c=new Vector3(.18f,alto*.55f,.1f);Tubo(g,Vector3.zero,c,.23f,.11f,9);Tubo(g,c,new Vector3(-.2f,alto,0),.11f,.025f);for(int b=0;b<6;b++){float ang=b*2.4f;Vector3 fin=c+new Vector3(Mathf.Cos(ang)*(variante==0?1.5f:2.1f),R(.5f,2.1f),Mathf.Sin(ang)*1.6f);Tubo(g,c*.75f,fin,.085f,.025f);for(int i=0;i<60;i++){Vector3 p=fin+new Vector3(R(-1.2f,1.2f),R(-.4f,1.0f),R(-1.1f,1.1f));Hoja(leaf,p,R(.5f,.95f),Quaternion.Euler(R(0,180),R(0,360),R(0,180)));}}for(int i=0;i<75;i++)Hoja(leaf,new Vector3(R(-.8f,.8f),R(alto-.7f,alto+.5f),R(-.8f,.8f)),R(.5f,.95f),Quaternion.Euler(R(0,180),R(0,360),R(0,180)));troncos=Asset(g.Mesh("Tronco queñua"),"Tronco"+variante+".asset");hojasMesh=Asset(leaf.Mesh("Copa queñua"),"Copa"+variante+".asset");}
